UPDATE "Founder" SET "quoteZh" = '教育是维护人的尊严、繁荣与国家发展的持久基石。在 SIT，我们不仅教育学生，更激励他们建设更美好的世界。' WHERE NULLIF(TRIM("quoteZh"), '') IS NULL AND "quote" = 'Education is the single most enduring foundation for human dignity, prosperity, and national transformation. At SIT, we do not merely educate students; we inspire them to build a better world.';
UPDATE "Founder" SET "biographyZh" = 'Oknha Mengly J. Quach 博士是教育先驱、医生、作家与慈善家，数十年来致力于推动柬埔寨教育发展。在他的领导下，SIT 发展成为以严谨学术、创新与全球合作著称的优秀学府。' WHERE NULLIF(TRIM("biographyZh"), '') IS NULL AND "biography" = 'A revered education pioneer, physician, author, and philanthropist, Oknha Dr. Mengly J. Quach has dedicated decades to advancing educational excellence in Cambodia. Under his visionary stewardship, SIT University has grown into a premier institution recognized for academic rigor, innovation, and global collaboration.';
