UPDATE "AdmissionRequirement" SET "requirementsListZh" = '["高中毕业证书（BacII）成绩至少为C级，或同等国际资格（A-Levels、IB、GED）","英语水平：雅思5.5及以上、托福 iBT 65及以上，或通过 SIT 英语分级考试","10、11和12年级的正式高中成绩单","身份证或护照复印件","两封高中教师或升学顾问推荐信","个人陈述／申请动机信（500词）"]' WHERE NULLIF(TRIM("requirementsListZh"), '') IS NULL AND "requirementsList" = '["High School Diploma (BacII) with minimum Grade C or international equivalent (A-Levels, IB, GED)","English Language Proficiency: IELTS 5.5+, TOEFL iBT 65+, or passing score on SIT English Placement Test","Official high school academic transcripts for Grades 10, 11, and 12","Copy of National Identification Card or Passport","Two letters of recommendation from high school teachers or counselors","Personal Statement / Motivation Letter (500 words)"]';
