UPDATE "AdmissionRequirement" SET "requirementsListZh" = '["相关领域认可学士学位，累计平均 GPA 至少为3.0／4.0","英语水平：雅思6.5及以上或托福 iBT 80及以上","正式本科学位证书及完整成绩单","最新简历，说明相关工作或研究经历","两封学术或职业推荐信","研究与职业目标陈述（800词）"]' WHERE NULLIF(TRIM("requirementsListZh"), '') IS NULL AND "requirementsList" = '["Accredited Bachelor’s Degree in a relevant field with a minimum cumulative GPA of 3.0 / 4.0","English Proficiency: IELTS 6.5+ or TOEFL iBT 80+","Official undergraduate degree certificate and complete academic transcripts","Updated Curriculum Vitae (CV) demonstrating relevant work or research experience","Two academic or professional letters of recommendation","Statement of Research & Career Intent (800 words)"]';
