UPDATE "AdmissionRequirement" SET "requirementsListZh" = '["有效护照（有效期至少一年）","中学或大学学历证书的认证英语译本","英语水平证明（雅思、托福或多邻国英语测试）","财务担保声明或银行证明，确认有足够资金支付学费与生活费","录取后提供学生签证（E类）申请支持"]' WHERE NULLIF(TRIM("requirementsListZh"), '') IS NULL AND "requirementsList" = '["Valid International Passport (minimum 1-year validity)","Certified English translation of secondary school or university degree certificates","Proof of English proficiency (IELTS, TOEFL, Duolingo English Test)","Financial affidavit or bank statement verifying sufficient funds for tuition and living expenses","Student Visa (Type E) application support provided upon acceptance"]';
